92	        ]);
93	      });
94	
95	      it('lässt die Auswahl der übrigen Sitzplätze unverändert, wenn ein anderer abgewählt wird', () => {
96	        const service = createService();
97	        service.toggle('A', 1);
98	        service.toggle('C', 5);
99	        service.toggle('A', 1);
100	        expect(service.selectedSeats()).toEqual([{ rowLabel: 'C', columnNumber: 5 }]);
