  height: 12px;
}

.seat-cell__icon--seat {
  border: 1.5px solid currentColor;
  border-radius: 2px;
}

.seat-cell__icon--lock {
  position: relative;
  border: 1.5px solid currentColor;
  border-radius: 2px;

  &::before {
    content: '';
    position: absolute;
    top: -5px;
    left: 2px;
    width: 6px;
    height: 5px;
    border: 1.5px solid currentColor;
    border-bottom: none;
    border-radius: 3px 3px 0 0;
  }
}

.seat-cell__label {
  font-size: var(--text-seat-label-size);
  font-weight: var(--text-seat-label-weight);
  line-height: 1;
}

